callGraph.callee:
(() => {
          const pl = previewLine;
          const isH = pl.type === 'h';
          const a = dotPos(pl.row, pl.col);
          const b = isH ? dotPos(pl.row, pl.col + 1) : dotPos(pl.row + 1, pl.col);
          const currentColor = state.currentPlayer === 1 ? theme.p1 : theme.p2;
          return (
            <Line
              key="preview"
              x1={a.x} y1={a.y} x2={b.x} y2={b.y}
              stroke={currentColor}
              strokeWidth={lineW}
              strokeLinecap="round"
              opacity={0.4}
            />
          );
        })

(async () => {
    try {
      await Audio.setAudioModeAsync({
        playsInSilentModeIOS:    true,
        staysActiveInBackground: false,
      });
      await Promise.all([
        writeAndLoad('click',     genClick()),
        writeAndLoad('pop',       genPop()),
        writeAndLoad('chain',     genChain()),
        writeAndLoad('win',       genWin()),
        writeAndLoad('draw',      genDraw()),
        writeAndLoad('timerBeep', genTimerBeep()),
      ]);
      initDone = true;
    } catch (e) {
      // Audio unavailable (simulator mute, etc.) — silently degrade
      console.warn('[audio] init failed:', e);
    }
  })
